function [ecc, inc, om, w] = vectors2elem(j, e)
%VECTORS2ELEM  thirdbody.secular.vectors2elem(j, e): eccentricity, inclination, RAAN and argument of perigee [rad] of the vectors
%   (the node along x when the orbit is equatorial, the perigee at the node when it is circular).
%   j: real[1][3] (passed a plain number)
%   e: real[1][3] (passed a plain number)
%   returns ecc: real[1] (passed a plain number)
%   returns inc: real[1] (passed a plain number)
%   returns om: real[1] (passed a plain number)
%   returns w: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ecc = 0;
    inc = 0;
    om = 0;
    w = 0;
    jn = asils.pc.norm_(j);
    ecc = asils.pc.norm_(e);
    inc = acos(asils.models.thirdbody.unit_clip((j(3) / jn)));
    node = asils.pc.cross_([0; 0; 1], j);
    nn = asils.pc.norm_(node);
    nodeu = [1; 0; 0];
    if (nn < 1e-12)
        om = 0;
    else
        om = atan2(node(2), node(1));
        nodeu = [(node(1) / nn); (node(2) / nn); (node(3) / nn)];
    end
    if (ecc < 1e-12)
        w = 0;
    else
        ehat = [(e(1) / ecc); (e(2) / ecc); (e(3) / ecc)];
        ip = asils.pc.cross_([(j(1) / jn); (j(2) / jn); (j(3) / jn)], nodeu);
        w = atan2(asils.pc.dot_(ip, ehat), asils.pc.dot_(nodeu, ehat));
    end
end
